from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
html=ROOT/'public'/'data_entry.html'
server=ROOT/'server.py'

h=html.read_text(encoding='utf-8')
s=server.read_text(encoding='utf-8')

if 'data-entry-pending-recall-v1' not in h:
    old_css="""@media(max-width:560px){.assignment-toolbar .btn{flex:1}.assignment-toolbar .muted{width:100%;margin:0;text-align:center}}\n\n</style>"""
    new_css="""@media(max-width:560px){.assignment-toolbar .btn{flex:1}.assignment-toolbar .muted{width:100%;margin:0;text-align:center}}\n\n/* data-entry-pending-recall-v1 */\n.pending-toolbar{border-color:#655a3b;background:#182313}.pending-select{width:20px;height:20px;accent-color:#d6b15a}.row.pending{border-color:#4d6580}.row .thumbs img{cursor:zoom-in}.de-viewer{position:fixed;inset:0;z-index:3000;background:#000d;display:flex;flex-direction:column;padding:10px}.de-viewer.hidden{display:none}.de-viewer-tools{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;padding:8px;background:#0a1929;border:1px solid #40566d;border-radius:12px}.de-viewer-stage{flex:1;min-height:0;overflow:hidden;display:grid;place-items:center;touch-action:none}.de-viewer-stage img{max-width:94%;max-height:94%;object-fit:contain;transform-origin:center;user-select:none;cursor:grab}.de-viewer-stage img:active{cursor:grabbing}.de-viewer-caption{text-align:center;padding:6px;color:#f0d995;font-weight:800}\n\n</style>"""
    if old_css not in h: raise SystemExit('CSS anchor not found')
    h=h.replace(old_css,new_css,1)

    old_toolbar="""        <div class=\"assignment-toolbar\">\n          <button id=\"selectAllDraftRows\" type=\"button\" class=\"smallbtn\">تحديد كل المسودات</button>\n          <button id=\"clearDraftSelection\" type=\"button\" class=\"smallbtn\">إلغاء التحديد</button>\n          <button id=\"assignSelectedDrafts\" type=\"button\" class=\"btn\">إرسال المحدد لمسؤول إدخال البيانات</button>\n          <span id=\"draftSelectionCount\" class=\"muted\">0 محدد</span>\n        </div>\n        <div id=\"rows\" class=\"rows\"></div>"""
    new_toolbar="""        <div class=\"assignment-toolbar\">\n          <button id=\"selectAllDraftRows\" type=\"button\" class=\"smallbtn\">تحديد كل المسودات</button>\n          <button id=\"clearDraftSelection\" type=\"button\" class=\"smallbtn\">إلغاء التحديد</button>\n          <button id=\"assignSelectedDrafts\" type=\"button\" class=\"btn\">إرسال المحدد لمسؤول إدخال البيانات</button>\n          <span id=\"draftSelectionCount\" class=\"muted\">0 محدد</span>\n        </div>\n        <div class=\"assignment-toolbar pending-toolbar\">\n          <button id=\"selectAllPendingRows\" type=\"button\" class=\"smallbtn\">تحديد كل المرسلة للاعتماد</button>\n          <button id=\"clearPendingSelection\" type=\"button\" class=\"smallbtn\">إلغاء التحديد</button>\n          <button id=\"withdrawSelectedPending\" type=\"button\" class=\"btn ghost\">↩ استرجاع المحدد للتعديل</button>\n          <span id=\"pendingSelectionCount\" class=\"muted\">0 محدد</span>\n        </div>\n        <div id=\"rows\" class=\"rows\"></div>"""
    if old_toolbar not in h: raise SystemExit('toolbar anchor not found')
    h=h.replace(old_toolbar,new_toolbar,1)

    old_block="""let selectedDraftRows=new Set();\nfunction syncDraftSelection(){\n  const drafts=rows.filter(r=>['draft','needs_changes'].includes(r.status));\n  selectedDraftRows=new Set([...selectedDraftRows].filter(id=>drafts.some(r=>String(r.id)===String(id))));\n  if($('draftSelectionCount'))$('draftSelectionCount').textContent=`${selectedDraftRows.size} محدد`;\n  if($('assignSelectedDrafts'))$('assignSelectedDrafts').disabled=!selectedDraftRows.size\n}\nwindow.toggleDraftRow=(id,checked)=>{checked?selectedDraftRows.add(String(id)):selectedDraftRows.delete(String(id));syncDraftSelection()};\nfunction renderRows(){\n  $('rows').innerHTML=rows.map(r=>{\n    const imgs=[r.frontImage,r.backImage,...(r.additionalImages||[])].filter(Boolean),editable=['draft','needs_changes','assigned'].includes(r.status),assignable=['draft','needs_changes'].includes(r.status),store=r.storeType==='collectibles'?'collectibles':'coins',category=store==='collectibles'?(CATEGORY_LABELS[r.collectibleCategory]||'أخرى'):'';\n    return`<article class=\"row ${esc(r.status||'')}\"><div style=\"display:flex;justify-content:space-between;gap:8px;align-items:center\"><div style=\"display:flex;gap:8px;align-items:center\">${assignable?`<input class=\"row-select\" type=\"checkbox\" aria-label=\"تحديد المسودة\" ${selectedDraftRows.has(String(r.id))?'checked':''} onchange=\"toggleDraftRow('${esc(r.id)}',this.checked)\">`:''}<h3>${esc(r.country||'—')} — ${esc(r.denomination||'—')}</h3></div><span class=\"chip\">${esc(statusLabel(r.status))}</span></div>\n    <div class=\"meta\"><span class=\"chip store-chip\">${esc(STORE_LABELS[store])}</span>${category?`<span>التصنيف: ${esc(category)}</span>`:''}<span>${esc(r.year||'')}</span><span>الكمية: ${Number(r.quantity||r.inventoryUnitCount||1)}</span><span>شراء: ${Number(r.purchase||0).toLocaleString('ar-SA')}</span><span>بيع: ${Number(r.salePrice||r.expectedPrice||0).toLocaleString('ar-SA')}</span></div>\n    ${imgs.length?`<div class=\"thumbs\">${imgs.slice(0,4).map(x=>`<img src=\"${esc(x)}\" alt=\"\">`).join('')}</div>`:''}${r.adminNote?`<div class=\"row-note\"><b>ملاحظة الإدارة:</b> ${esc(r.adminNote)}</div>`:''}\n    <div class=\"actions\">${editable?`<button class=\"smallbtn\" onclick=\"editRow('${esc(r.id)}')\">${r.status==='assigned'?'فتح وإكمال':'تعديل'}</button>`:''}</div></article>`\n  }).join('')||'<p class=\"muted\">لا توجد سجلات بعد. ابدأ بإضافة أول مقتنى.</p>';\n  syncDraftSelection()\n}\n$('selectAllDraftRows').onclick=()=>{selectedDraftRows=new Set(rows.filter(r=>['draft','needs_changes'].includes(r.status)).map(r=>String(r.id)));renderRows()};\n$('clearDraftSelection').onclick=()=>{selectedDraftRows.clear();renderRows()};\n$('assignSelectedDrafts').onclick=async()=>{\n  const ids=[...selectedDraftRows];if(!ids.length)return;\n  if(!confirm(`إرسال ${ids.length} مسودة لمسؤول إدخال البيانات؟`))return;\n  $('assignSelectedDrafts').disabled=true;let ok=0,failed=0;\n  for(const id of ids){try{await api('/api/data-entry/submissions',{method:'POST',body:JSON.stringify({id,mode:'assign'})});ok++}catch(e){failed++}}\n  selectedDraftRows.clear();await loadRows();setNotice(failed?`تم إرسال ${ok} وتعذر ${failed}.`:`تم إرسال ${ok} مسودة لمسؤول إدخال البيانات وأصبحت «قيد الإدخال».`,failed?'warn':'good')\n};"""
    new_block="""let selectedDraftRows=new Set(),selectedPendingRows=new Set();\nfunction syncDraftSelection(){\n  const drafts=rows.filter(r=>['draft','needs_changes'].includes(r.status));\n  const pending=rows.filter(r=>r.status==='pending');\n  selectedDraftRows=new Set([...selectedDraftRows].filter(id=>drafts.some(r=>String(r.id)===String(id))));\n  selectedPendingRows=new Set([...selectedPendingRows].filter(id=>pending.some(r=>String(r.id)===String(id))));\n  if($('draftSelectionCount'))$('draftSelectionCount').textContent=`${selectedDraftRows.size} محدد`;\n  if($('pendingSelectionCount'))$('pendingSelectionCount').textContent=`${selectedPendingRows.size} محدد`;\n  if($('assignSelectedDrafts'))$('assignSelectedDrafts').disabled=!selectedDraftRows.size;\n  if($('withdrawSelectedPending'))$('withdrawSelectedPending').disabled=!selectedPendingRows.size\n}\nwindow.toggleDraftRow=(id,checked)=>{checked?selectedDraftRows.add(String(id)):selectedDraftRows.delete(String(id));syncDraftSelection()};\nwindow.togglePendingRow=(id,checked)=>{checked?selectedPendingRows.add(String(id)):selectedPendingRows.delete(String(id));syncDraftSelection()};\n\nlet DEVIEW={imgs:[],idx:0,scale:1,x:0,y:0,drag:false,px:0,py:0};\nfunction drawDEViewer(){const im=document.getElementById('deViewerImg');if(im)im.style.transform=`translate(${DEVIEW.x}px,${DEVIEW.y}px) scale(${DEVIEW.scale})`;const c=document.getElementById('deViewerCaption');if(c)c.textContent=DEVIEW.imgs.length?`${DEVIEW.idx+1} / ${DEVIEW.imgs.length}`:''}\nwindow.previewRowImages=(id,idx=0)=>{const r=rows.find(x=>String(x.id)===String(id));if(!r)return;DEVIEW.imgs=[r.frontImage,r.backImage,...(r.additionalImages||[])].filter(Boolean);if(!DEVIEW.imgs.length)return;DEVIEW.idx=Math.max(0,Math.min(idx,DEVIEW.imgs.length-1));DEVIEW.scale=1;DEVIEW.x=DEVIEW.y=0;let v=document.getElementById('deViewer');if(!v){v=document.createElement('div');v.id='deViewer';v.className='de-viewer';v.innerHTML=`<div class=\"de-viewer-tools\"><button class=\"smallbtn\" data-dv=\"close\">✕ إغلاق</button><button class=\"smallbtn\" data-dv=\"prev\">‹ السابق</button><button class=\"smallbtn\" data-dv=\"zin\">＋ تكبير</button><button class=\"smallbtn\" data-dv=\"zout\">− تصغير</button><button class=\"smallbtn\" data-dv=\"reset\">إظهار كامل</button><button class=\"smallbtn\" data-dv=\"next\">التالي ›</button></div><div class=\"de-viewer-stage\"><img id=\"deViewerImg\" alt=\"معاينة\"></div><div id=\"deViewerCaption\" class=\"de-viewer-caption\"></div>`;document.body.appendChild(v);v.querySelectorAll('[data-dv]').forEach(b=>b.onclick=()=>{const a=b.dataset.dv;if(a==='close'){v.classList.add('hidden');return}if(a==='prev')DEVIEW.idx=(DEVIEW.idx-1+DEVIEW.imgs.length)%DEVIEW.imgs.length;if(a==='next')DEVIEW.idx=(DEVIEW.idx+1)%DEVIEW.imgs.length;if(a==='zin')DEVIEW.scale=Math.min(6,DEVIEW.scale+.25);if(a==='zout')DEVIEW.scale=Math.max(.35,DEVIEW.scale-.25);if(a==='reset'){DEVIEW.scale=1;DEVIEW.x=DEVIEW.y=0}document.getElementById('deViewerImg').src=DEVIEW.imgs[DEVIEW.idx];drawDEViewer()});const st=v.querySelector('.de-viewer-stage');st.onpointerdown=e=>{DEVIEW.drag=true;DEVIEW.px=e.clientX;DEVIEW.py=e.clientY;st.setPointerCapture?.(e.pointerId)};st.onpointermove=e=>{if(!DEVIEW.drag)return;DEVIEW.x+=e.clientX-DEVIEW.px;DEVIEW.y+=e.clientY-DEVIEW.py;DEVIEW.px=e.clientX;DEVIEW.py=e.clientY;drawDEViewer()};st.onpointerup=st.onpointercancel=()=>DEVIEW.drag=false;st.onwheel=e=>{e.preventDefault();DEVIEW.scale=Math.max(.35,Math.min(6,DEVIEW.scale+(e.deltaY<0?.2:-.2)));drawDEViewer()}}v.classList.remove('hidden');document.getElementById('deViewerImg').src=DEVIEW.imgs[DEVIEW.idx];drawDEViewer()};\n\nfunction renderRows(){\n  $('rows').innerHTML=rows.map(r=>{\n    const imgs=[r.frontImage,r.backImage,...(r.additionalImages||[])].filter(Boolean),editable=['draft','needs_changes','assigned'].includes(r.status),assignable=['draft','needs_changes'].includes(r.status),recallable=r.status==='pending',store=r.storeType==='collectibles'?'collectibles':'coins',category=store==='collectibles'?(CATEGORY_LABELS[r.collectibleCategory]||'أخرى'):'';\n    const selector=assignable?`<input class=\"row-select\" type=\"checkbox\" aria-label=\"تحديد المسودة\" ${selectedDraftRows.has(String(r.id))?'checked':''} onchange=\"toggleDraftRow('${esc(r.id)}',this.checked)\">`:recallable?`<input class=\"pending-select\" type=\"checkbox\" aria-label=\"تحديد المرسل للاعتماد\" ${selectedPendingRows.has(String(r.id))?'checked':''} onchange=\"togglePendingRow('${esc(r.id)}',this.checked)\">`:'';\n    return`<article class=\"row ${esc(r.status||'')}\"><div style=\"display:flex;justify-content:space-between;gap:8px;align-items:center\"><div style=\"display:flex;gap:8px;align-items:center\">${selector}<h3>${esc(r.country||'—')} — ${esc(r.denomination||'—')}</h3></div><span class=\"chip\">${esc(statusLabel(r.status))}</span></div>\n    <div class=\"meta\"><span class=\"chip store-chip\">${esc(STORE_LABELS[store])}</span>${category?`<span>التصنيف: ${esc(category)}</span>`:''}<span>${esc(r.year||'')}</span><span>الكمية: ${Number(r.quantity||r.inventoryUnitCount||1)}</span><span>شراء: ${Number(r.purchase||0).toLocaleString('ar-SA')}</span><span>بيع: ${Number(r.salePrice||r.expectedPrice||0).toLocaleString('ar-SA')}</span></div>\n    ${imgs.length?`<div class=\"thumbs\">${imgs.slice(0,4).map((x,n)=>`<img src=\"${esc(x)}\" alt=\"\" onclick=\"previewRowImages('${esc(r.id)}',${n})\">`).join('')}</div>`:''}${r.adminNote?`<div class=\"row-note\"><b>ملاحظة الإدارة:</b> ${esc(r.adminNote)}</div>`:''}\n    <div class=\"actions\">${imgs.length?`<button class=\"smallbtn\" onclick=\"previewRowImages('${esc(r.id)}',0)\">معاينة الصور</button>`:''}${editable?`<button class=\"smallbtn\" onclick=\"editRow('${esc(r.id)}')\">${r.status==='assigned'?'فتح وإكمال':'تعديل'}</button>`:''}${recallable?`<button class=\"smallbtn\" onclick=\"withdrawPendingRows(['${esc(r.id)}'])\">↩ استرجاع للتعديل</button>`:''}</div></article>`\n  }).join('')||'<p class=\"muted\">لا توجد سجلات بعد. ابدأ بإضافة أول مقتنى.</p>';\n  syncDraftSelection()\n}\n$('selectAllDraftRows').onclick=()=>{selectedDraftRows=new Set(rows.filter(r=>['draft','needs_changes'].includes(r.status)).map(r=>String(r.id)));renderRows()};\n$('clearDraftSelection').onclick=()=>{selectedDraftRows.clear();renderRows()};\n$('selectAllPendingRows').onclick=()=>{selectedPendingRows=new Set(rows.filter(r=>r.status==='pending').map(r=>String(r.id)));renderRows()};\n$('clearPendingSelection').onclick=()=>{selectedPendingRows.clear();renderRows()};\n$('assignSelectedDrafts').onclick=async()=>{\n  const ids=[...selectedDraftRows];if(!ids.length)return;\n  if(!confirm(`إرسال ${ids.length} مسودة لمسؤول إدخال البيانات؟`))return;\n  $('assignSelectedDrafts').disabled=true;let ok=0,failed=0;\n  for(const id of ids){try{await api('/api/data-entry/submissions',{method:'POST',body:JSON.stringify({id,mode:'assign'})});ok++}catch(e){failed++}}\n  selectedDraftRows.clear();await loadRows();setNotice(failed?`تم إرسال ${ok} وتعذر ${failed}.`:`تم إرسال ${ok} مسودة لمسؤول إدخال البيانات وأصبحت «قيد الإدخال».`,failed?'warn':'good')\n};\nwindow.withdrawPendingRows=async(ids)=>{ids=(ids||[]).filter(Boolean);if(!ids.length)return;if(!confirm(`استرجاع ${ids.length} مقتنى من انتظار الاعتماد إلى «قيد الإدخال» للتعديل؟`))return;let ok=0,failed=0;for(const id of ids){try{await api('/api/data-entry/submissions',{method:'POST',body:JSON.stringify({id,mode:'withdraw'})});ok++}catch(e){failed++}}selectedPendingRows.clear();await loadRows();setNotice(failed?`تم استرجاع ${ok} وتعذر ${failed}.`:`تم استرجاع ${ok} مقتنى. يمكنك الآن فتحه وتعديله ثم إرساله للاعتماد مرة أخرى.`,failed?'warn':'good')};\n$('withdrawSelectedPending').onclick=()=>withdrawPendingRows([...selectedPendingRows]);"""
    if old_block not in h: raise SystemExit('selection/render block anchor not found')
    h=h.replace(old_block,new_block,1)

if "mode not in ('draft','submit','assign','withdraw')" not in s:
    old="""                if mode not in ('draft','submit','assign'): mode='draft'"""
    new="""                if mode not in ('draft','submit','assign','withdraw'): mode='draft'"""
    if old not in s: raise SystemExit('server mode anchor not found')
    s=s.replace(old,new,1)

    anchor="""                    if not row:\n                        self.sendj({'error':'سجل الإدخال غير موجود'},404); return\n                    if mode=='assign':"""
    replacement="""                    if not row:\n                        self.sendj({'error':'سجل الإدخال غير موجود'},404); return\n                    if mode=='withdraw':\n                        if row.get('status')!='pending':\n                            self.sendj({'error':'يمكن استرجاع المقتنى فقط وهو بانتظار الاعتماد وقبل صدور قرار الإدارة'},409); return\n                        now=datetime.datetime.now().isoformat()\n                        row['status']='assigned'; row['withdrawnAt']=now; row['updated']=now\n                        save_json(COLLECTIBLE_SUBMISSIONS,{'submissions':rows})\n                        add_notification('admin','','approval','↩ تم استرجاع مقتنى من الاعتماد',f\"استرجع مسؤول إدخال البيانات {row.get('dataEntryName') or 'المسؤول'} مقتنى قبل اعتماد الإدارة لإجراء تعديل عليه.\",sid,'/admin')\n                        append_operation('استرجاع مقتنى من انتظار الاعتماد للتعديل',{'submissionId':sid,'operatorId':pid},actor='مسؤول إدخال البيانات')\n                        self.sendj({'ok':True,'submission':row}); return\n                    if mode=='assign':"""
    if anchor not in s: raise SystemExit('server withdraw anchor not found')
    s=s.replace(anchor,replacement,1)

html.write_text(h,encoding='utf-8')
server.write_text(s,encoding='utf-8')
print('patched data-entry pending recall and preview')
